class BadWhen {
    fun render(type: String) {
        var result = ""
        when (type) {
            "A" -> result = "case1"
            "B" -> result = "case1" // bad
            "C" -> result = "case2"
        }
        println(result)
    }
}

class GoodWhenExpression {
    fun render(type: String): String {
        return when (type) {
            "A" -> "case1"
            "B" -> "case2"
            else -> "default"
        }
    }
}

class GoodWhenAssignments {
    fun render(type: String) {
        var result = ""
        when (type) {
            "A" -> result = "case1"
            "B" -> result = "case2"
            else -> result = "default"
        }
        println(result)
    }
}
